import React, { useState } from 'react';
import RegisterTeam from './RegisterTeam';
import Login from './Login';
import CluePage from './CluePage';
import Leaderboard from './Leaderboard';
import './App.css';

// Welcome component for the initial page
function Welcome({ setCurrentPage }) {
  return (
    <div className="welcome-container">
      <h1>Verdentra Mystery Hunt</h1>
      <h2>Welcome to the Treasure Hunt!</h2>
      
      <div className="welcome-description">
        <p>Embark on an exciting journey of riddles and puzzles. Solve clues, find the treasure, and compete with other teams!</p>
      </div>
      
      <div className="welcome-buttons">
        <button onClick={() => setCurrentPage('register')} className="register-button">
          Register New Team
        </button>
        <button onClick={() => setCurrentPage('login')} className="login-button">
          Login to Existing Team
        </button>
      </div>
      
      <div className="welcome-leaderboard-link">
        <button onClick={() => setCurrentPage('leaderboard')} className="leaderboard-link-button">
          View Leaderboard
        </button>
      </div>
    </div>
  );
}

function App() {
  const [teamId, setTeamId] = useState(null);
  const [currentPage, setCurrentPage] = useState('register');

  return (
    <div className="App">
      <div className="container">
        {currentPage === 'register' && <RegisterTeam setTeamId={setTeamId} setCurrentPage={setCurrentPage} />}
        {currentPage === 'login' && <Login setTeamId={setTeamId} setCurrentPage={setCurrentPage} />}
        {currentPage === 'game' && <CluePage teamId={teamId} setCurrentPage={setCurrentPage} />}
        {currentPage === 'leaderboard' && <Leaderboard setCurrentPage={setCurrentPage} />}
      </div>
    </div>
  );
}

export default App;
